+
+      .card {
+        width: min(100%, 28rem);
+        padding: 2rem;
+        border: 1px solid var(--surface-border);
+        border-radius: 1.5rem;
+        background: var(--surface);
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        margin: 0 0 0.75rem;
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.08em;
+        text-transform: uppercase;
+        color: var(--primary);
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(1.8rem, 4vw, 2.35rem);
+        line-height: 1.1;
+      }
+
+      .intro {
+        margin: 0.9rem 0 1.5rem;
+        color: var(--muted);
+        line-height: 1.6;
+      }
+
+      form {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.5rem;
+        padding: 1rem;
+        border: 1px solid var(--surface-border);
+        border-radius: 1rem;
+        background: #f9fbff;
+      }
+
+      .checkbox-row {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.85rem;
+        align-items: start;
+      }
+
+      input[type="checkbox"] {
+        inline-size: 1.15rem;
+        block-size: 1.15rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--primary);
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.5;
+      }
+
+      .required {
+        color: var(--primary-strong);
+      }
+
+      .helper-text,
+      .error-text,
+      .status {
+        margin: 0;
+        font-size: 0.95rem;
+        line-height: 1.5;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: #b42318;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        color: var(--success-text);
+      }
+
+      .status[data-visible="true"] {
+        padding: 0.85rem 1rem;
+        border-radius: 0.9rem;
+        background: var(--success-bg);
+      }
+
+      button {
+        border: 0;
+        border-radius: 999px;
+        padding: 0.95rem 1.25rem;
+        font: inherit;
+        font-weight: 700;
+        color: #ffffff;
+        background: linear-gradient(180deg, var(--primary) 0%, var(--primary-strong) 100%);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.05);
+      }
+
+      a,
+      input,
+      button {
+        outline-offset: 3px;
+      }
+
+      a:focus-visible,
+      input:focus-visible,
+      button:focus-visible {
+        outline: 3px solid #0f172a;
+      }
+
+      @media (max-width: 480px) {
+        .card {
+          padding: 1.5rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --bg: Canvas;
+          --surface: Canvas;
+          --surface-border: ButtonBorder;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --primary: Highlight;
+          --primary-strong: Highlight;
+          --success-bg: Canvas;
+          --success-text: CanvasText;
+          --shadow: none;
+        }
+
+        .skip-link,
+        button {
+          border: 1px solid ButtonBorder;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content">
+      <section class="card" aria-labelledby="form-title">
+        <p class="eyebrow">Account setup</p>
+        <h1 id="form-title">Confirm your consent</h1>
+        <p class="intro">
+          Review the terms and confirm your agreement before continuing.
+        </p>
+
+        <form id="consent-form" novalidate>
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="consent"
+                name="consent"
+                type="checkbox"
+                required
+                aria-describedby="consent-helper consent-error"
+              />
+              <label for="consent">
+                I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
+              </label>
+            </div>
+            <p id="consent-helper" class="helper-text">
+              Required to continue with your submission.
+            </p>
+            <p id="consent-error" class="error-text" hidden>
+              Please agree to the Terms of Use before submitting.
+            </p>
+          </div>
+
+          <button type="submit">Submit</button>
+          <p id="form-status" class="status" aria-live="polite"></p>
+        </form>
+      </section>
+    </main>
+
+    <script>
+      const form = document.getElementById("consent-form");
+      const consent = document.getElementById("consent");
+      const errorText = document.getElementById("consent-error");
+      const status = document.getElementById("form-status");
+
+      function setErrorState(showError) {
+        consent.setAttribute("aria-invalid", showError ? "true" : "false");
+        errorText.hidden = !showError;
+      }
+
+      consent.addEventListener("change", () => {
+        if (consent.checked) {
+          setErrorState(false);
+        }
+      });
+
+      form.addEventListener("submit", (event) => {
+        status.textContent = "";
+        status.dataset.visible = "false";
+
+        if (!consent.checked) {
+          event.preventDefault();
+          setErrorState(true);
+          consent.focus();
+          return;
+        }
+
+        event.preventDefault();
+        setErrorState(false);
+        status.textContent = "Consent recorded. You can proceed.";
+        status.dataset.visible = "true";
+        form.reset();
+      });
+    </script>
+  </body>
+</html>
*** End Patch
